(function(){
  var pages=document.querySelectorAll('.page');
  var modal=document.getElementById('slotModal');
  var closeModal=document.getElementById('closeModal');
  var favorites={};
  var toastTimer;

  function closeNavbar(){
    var menu=document.getElementById('mainNavbar');var toggler=document.querySelector('.brand-portrait');
    if(menu){menu.classList.remove('show'); if(window.innerWidth>=992){menu.style.display='none';}}
    if(toggler){toggler.setAttribute('aria-expanded','false')}
    var brandLockup=document.querySelector('.brand-lockup');
    if(brandLockup){brandLockup.classList.remove('menu-open')}
    document.querySelectorAll('.dropdown-menu.show').forEach(function(dropdown){dropdown.classList.remove('show')});
  }
  function showPage(id){
    pages.forEach(function(p){p.classList.toggle('active',p.id===id)});
    document.querySelectorAll('.site-nav [data-page]').forEach(function(b){b.classList.toggle('active',b.dataset.page===id)});
    modal.classList.remove('open');
    closeNavbar();
    window.scrollTo({top:0,behavior:'auto'});
  }
  function showToast(message){
    var toast=document.getElementById('favoriteToast');
    toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);
    toastTimer=setTimeout(function(){toast.classList.remove('show')},1800);
  }
  function setFavoriteState(id,on){
    document.querySelectorAll('.poster[data-card-id="'+id+'"] .favorite-btn').forEach(function(button){
      button.classList.toggle('is-favorite',on);
      var title=button.closest('.poster').dataset.title||'Photo';
      button.setAttribute('aria-label',(on?'Remove ':'Add ')+title+(on?' from favourites':' to favourites'));
      button.title=on?'Remove from favourites':'Add to favourites';
    });
  }
  function renderFavorites(){
    var grid=document.getElementById('favoritesGrid');
    var empty=document.getElementById('favoritesEmpty');
    var ids=Object.keys(favorites);grid.innerHTML='';
    ids.forEach(function(id){
      var source=document.querySelector('.poster[data-card-id="'+id+'"]');
      if(!source)return;
      var copy=source.cloneNode(true);copy.querySelector('.favorite-btn').classList.add('is-favorite');grid.appendChild(copy);
    });
    empty.classList.toggle('hidden',ids.length>0);
    document.getElementById('navFavoriteCount').textContent=ids.length;
  }
  function toggleFavorite(card){
    var id=card.dataset.cardId;var title=card.dataset.title||'Photo';
    if(favorites[id]){delete favorites[id];setFavoriteState(id,false);showToast(title+' removed from favourites')}
    else{favorites[id]=true;setFavoriteState(id,true);showToast(title+' added for this visit')}
    renderFavorites();
  }
  function openCard(card){
    if(card.dataset.href){window.open(card.dataset.href,'_blank','noopener,noreferrer');return}
    document.getElementById('modalTitle').textContent=card.dataset.placeholder==='true'?'Ready to personalize':(card.dataset.title||'Photo');
    document.getElementById('modalText').textContent='This starter card has no external link yet. Send your photo, text, and exact destination to replace it.';
    modal.classList.add('open');closeModal.focus();
  }
  function applyGalleryFilter(value){
    var visible=0;
    document.querySelectorAll('#galleryGrid .poster').forEach(function(card){
      var show=value==='all'||card.dataset.category===value;card.classList.toggle('hidden',!show);if(show)visible++;
    });
    document.getElementById('galleryEmpty').classList.toggle('hidden',visible>0);
  }
  function slotMarkup(id,label,number,category){
    var art=['art-one','art-two','art-three','art-four'][(number-1)%4];
    var categoryAttr=category?' data-category="'+category+'"':'';
    return '<article class="poster" tabindex="0" role="button" data-card-id="'+id+'" data-title="'+label+' photo" data-placeholder="true"'+categoryAttr+' aria-label="Empty '+label+' photo"><span class="poster-art '+art+'"></span><button class="favorite-btn" type="button" aria-label="Add '+label+' photo to favourites" title="Add to favourites"><svg viewBox="0 0 24 24"><path d="m12 20-1.35-1.23C5.86 14.42 3 11.82 3 8.63 3 6.03 5.03 4 7.63 4c1.47 0 2.88.68 3.8 1.75A5.06 5.06 0 0 1 15.37 4C17.97 4 20 6.03 20 8.63c0 3.19-2.86 5.79-7.65 10.15L12 20Z"/></svg></button></article>';
  }
  function buildPhotoSlots(){
    document.querySelectorAll('[data-fill-to]').forEach(function(grid){
      var target=Number(grid.dataset.fillTo)||20;var prefix=grid.dataset.prefix||'Photo';var start=grid.querySelectorAll('.poster').length+1;var html='';
      for(var i=start;i<=target;i++){html+=slotMarkup((prefix+'-'+i).toLowerCase().replace(/\s+/g,'-'),prefix,i,'')}
      grid.insertAdjacentHTML('beforeend',html);
    });
    var gallery=document.getElementById('galleryGrid');
    ['indian','hollywood','webseries'].forEach(function(category){
      var html='';var label=category==='webseries'?'Webseries':category.charAt(0).toUpperCase()+category.slice(1);
      for(var i=1;i<=20;i++){html+=slotMarkup(category+'-'+i,label,i,category)}
      gallery.insertAdjacentHTML('beforeend',html);
    });
  }

  /*
    UNLIMITED PHOTO LIBRARY
    Add more objects to PHOTO_ITEMS — there is no maximum. Put each image in
    assets/, choose one of the grid IDs shown in the Replacement Guide, and
    keep the full destination in href. The page renders only the photo; the
    title, alt text, and URL stay available for accessibility and click action.
  */
  var PHOTO_ITEMS=[
    {
      id:'gallary-dinosaur',
      grid:'galleryGrid',
      category:'link',
      title:'gallary',
      image:'data:image/jpeg;base64,',
      alt:'Colorful illustrated dinosaur wearing oversized red glasses',
      href:'https://t.me/AnimeStardust'
    },
    {
      id:'doccument-pinterest',
      grid:'telegramGrid',
      title:'DOCCUMENT',
      embed:'https://assets.pinterest.com/ext/embed.html?id=714102084703116659',
      href:'https://t.me/+y7ZsefjhObwxN2Fl',
      alt:'DOCCUMENT Pinterest image'
    },
    {
      id:'family-pinterest',
      grid:'telegramGrid',
      title:'FAMILY',
      embed:'https://assets.pinterest.com/ext/embed.html?id=126945283241587850',
      href:'https://t.me/+XR4ez1mMFe45Y2Jl',
      alt:'FAMILY Pinterest image'
    }
  ];
  function renderPhotoItems(){
    PHOTO_ITEMS.forEach(function(item,index){
      var grid=document.getElementById(item.grid);
      if(!grid||(!item.image&&!item.embed))return;
      grid.appendChild(createPhotoCard(item,index));
    });
  }
  function createPhotoCard(item,index){
      var card=document.createElement('article');
      card.className='poster';card.tabIndex=0;card.dataset.cardId=item.id||('photo-'+index);
      card.dataset.title=item.title||'Photo';
      if(item.category)card.dataset.category=item.category;
      if(item.href){card.dataset.href=item.href;card.setAttribute('role','link');card.setAttribute('aria-label','Open '+(item.title||'photo'))}
      else{card.dataset.placeholder='true';card.setAttribute('role','button');card.setAttribute('aria-label',item.title||'Photo')}
      if(item.embed){var embed=document.createElement('iframe');embed.className='poster-art poster-embed';embed.src=item.embed;embed.title=item.title||'Embedded image';embed.setAttribute('loading','lazy');embed.setAttribute('scrolling','no');embed.frameBorder='0';card.appendChild(embed)}
      else{var image=document.createElement('img');image.className='poster-art poster-image';image.src=item.image;image.alt=item.alt||'';card.appendChild(image)}
      if(item.title){var title=document.createElement('h2');title.className='poster-title';title.textContent=item.title;card.appendChild(title)}
      var favorite=document.createElement('button');favorite.className='favorite-btn';favorite.type='button';favorite.title='Add to favourites';favorite.setAttribute('aria-label','Add '+(item.title||'photo')+' to favourites');favorite.innerHTML='<svg viewBox="0 0 24 24"><path d="m12 20-1.35-1.23C5.86 14.42 3 11.82 3 8.63 3 6.03 5.03 4 7.63 4c1.47 0 2.88.68 3.8 1.75A5.06 5.06 0 0 1 15.37 4C17.97 4 20 6.03 20 8.63c0 3.19-2.86 5.79-7.65 10.15L12 20Z"/></svg>';
      card.appendChild(favorite);return card;
  }
  renderPhotoItems();
  buildPhotoSlots();

  var navToggler=document.querySelector('.brand-portrait');
  var menu=document.getElementById('mainNavbar');
  if(menu){menu.style.display='none';}
  navToggler.addEventListener('click',function(){
    var menu=document.getElementById('mainNavbar');
    var open=menu.classList.toggle('show');
    if(window.innerWidth>=992){menu.style.display=open?'block':'none';}
    navToggler.setAttribute('aria-expanded',String(open));
    document.querySelector('.brand-lockup').classList.toggle('menu-open',open);
  });
  document.querySelector('.dropdown-toggle').addEventListener('click',function(e){e.preventDefault();var dropdown=this.nextElementSibling;var open=dropdown.classList.toggle('show');this.setAttribute('aria-expanded',String(open))});
  document.querySelectorAll('[data-page]').forEach(function(btn){btn.addEventListener('click',function(e){var id=btn.dataset.page;if(id){e.preventDefault();showPage(id)}})});
  document.querySelectorAll('[data-movie-filter]').forEach(function(btn){btn.addEventListener('click',function(){
    document.querySelectorAll('.chip').forEach(function(c){c.classList.remove('active')});
    showPage('gallery');applyGalleryFilter(btn.dataset.movieFilter);
  })});
  document.addEventListener('click',function(e){
    var favoriteButton=e.target.closest('.favorite-btn');
    if(favoriteButton){e.preventDefault();e.stopPropagation();toggleFavorite(favoriteButton.closest('.poster'));return}
    var card=e.target.closest('.poster');if(card)openCard(card);
    var listItem=e.target.closest('.list-item');if(listItem&&!listItem.closest('#resultList')){
      document.getElementById('modalTitle').textContent=listItem.dataset.title||'Ready to personalize';modal.classList.add('open');closeModal.focus();
    }
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape')modal.classList.remove('open');
    if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('poster')){e.preventDefault();openCard(e.target)}
  });
  closeModal.addEventListener('click',function(){modal.classList.remove('open')});
  modal.addEventListener('click',function(e){if(e.target===modal)modal.classList.remove('open')});
  document.querySelectorAll('.chip').forEach(function(chip){chip.addEventListener('click',function(){
    document.querySelectorAll('.chip').forEach(function(c){c.classList.remove('active')});chip.classList.add('active');applyGalleryFilter(chip.dataset.filter);
  })});
  var searchBox=document.getElementById('compactSearch');
  var searchToggle=document.getElementById('searchToggle');
  var input=document.getElementById('searchInput');
  var mobileSearchInput=document.getElementById('mobileSearchInput');
  searchToggle.addEventListener('click',function(){
    var open=searchBox.classList.toggle('open');searchToggle.setAttribute('aria-expanded',String(open));searchToggle.setAttribute('aria-label',open?'Close search':'Open search');
    if(open){input.hidden=false;input.focus()}else{input.value='';input.hidden=true}
  });
  function runSearch(searchInput){
    var q=searchInput.value.trim().toLowerCase();if(!q)return;
    var matches=[];var seen={};document.querySelectorAll('[data-title]').forEach(function(item){var title=item.dataset.title||'';if(title.toLowerCase().indexOf(q)>-1&&!seen[title]){seen[title]=true;matches.push(title)}});
    var list=document.getElementById('resultList');list.innerHTML='';
    matches.forEach(function(title){var row=document.createElement('button');row.className='list-item';row.innerHTML='<span class="thumb art-three"></span><span><h3></h3><p>Content card</p></span><span class="arrow">↗</span>';row.querySelector('h3').textContent=title;row.addEventListener('click',function(){document.getElementById('modalTitle').textContent=title;modal.classList.add('open')});list.appendChild(row)});
    document.getElementById('noResults').classList.toggle('hidden',matches.length>0);
    document.getElementById('searchSummary').textContent=matches.length+' result'+(matches.length===1?'':'s')+' for “'+q+'”';showPage('searchResults');
  }
  input.addEventListener('input',function(){runSearch(input)});
  mobileSearchInput.addEventListener('input',function(){runSearch(mobileSearchInput)});
  renderFavorites();
})();
